def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_my, last_opp = history[-1]
    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    opp_d = 0
    my_d = 0
    for h in history:
        if h[1] == 'D':
            opp_d += 1
        if h[0] == 'D':
            my_d += 1

    recent_len = 20 if n >= 20 else n
    opp_d_recent = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            opp_d_recent += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break
    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    rd = 0
    rdd = 0
    rc = 0
    rcd = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            rd += 1
            if history[i + 1][1] == 'D':
                rdd += 1
        else:
            rc += 1
            if history[i + 1][1] == 'D':
                rcd += 1

    trans_start = n - 11
    if trans_start < 0:
        trans_start = 0
    rd_rec = 0
    rdd_rec = 0
    rc_rec = 0
    rcd_rec = 0
    for i in range(trans_start, n - 1):
        if history[i][0] == 'D':
            rd_rec += 1
            if history[i + 1][1] == 'D':
                rdd_rec += 1
        else:
            rc_rec += 1
            if history[i + 1][1] == 'D':
                rcd_rec += 1

    if rd_rec + rc_rec >= 5:
        rd_eff = rd_rec
        rdd_eff = rdd_rec
        rc_eff = rc_rec
        rcd_eff = rcd_rec
    else:
        rd_eff = rd
        rdd_eff = rdd
        rc_eff = rc
        rcd_eff = rcd

    if rd_eff == 0:
        p_punish = 0.65
    elif rdd_eff == 0:
        p_punish = 0.10 if rd_eff >= 3 else 0.25
    else:
        p_punish = (rdd_eff + 0.8) / (rd_eff + 1.6)

    if rc_eff == 0:
        p_unprov = opp_d / float(n)
    elif rcd_eff == 0:
        p_unprov = 0.08 if rc_eff >= 3 else 0.15
    else:
        p_unprov = (rcd_eff + 0.8) / (rc_eff + 1.6)

    hostile = False
    if n >= 10:
        if opp_d * 5 >= n * 3:
            hostile = True
        elif opp_d_streak >= 5 and p_unprov > 0.45:
            hostile = True
        elif opp_d_recent * 5 >= recent_len * 3 and opp_d * 3 >= n and p_unprov > 0.35:
            hostile = True

    data_eff = rd_eff + rc_eff
    conditional = False
    if data_eff >= 5:
        if p_punish > 0.55 and p_unprov < 0.40 and p_punish > p_unprov + 0.25:
            conditional = True

    exploitable = False
    if (not hostile) and (not conditional):
        if rd_eff >= 1 and rdd_eff == 0 and p_unprov < 0.40:
            exploitable = True
        elif rd_eff >= 2 and p_punish < 0.45 and p_unprov < 0.45:
            exploitable = True

    independent = False
    if not conditional:
        if rc_eff >= 3 and p_unprov > 0.55:
            independent = True
        elif rc_eff < 3 and n >= 8 and opp_d * 5 >= n * 3:
            independent = True
        elif rd_eff >= 3 and p_punish > 0.15 and abs(p_punish - p_unprov) < 0.22:
            independent = True

    if n == 6 and opp_d == 0 and my_d == 0:
        return 'D'

    if n >= 99:
        return 'D'
    if n == 98:
        if conditional and not hostile and not independent and not exploitable:
            if opp_d <= 1 and last_opp == 'C' and last_my == 'C':
                return 'C'
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'D':
                if opp_d_streak >= 3:
                    return 'D'
                if hostile or independent:
                    return 'D'
                return 'C'
            else:
                return 'D'
        else:
            if hostile or independent:
                return 'D'
            if opp_d_streak >= 3:
                return 'D'
            if p_unprov > 0.55:
                return 'D'
            return 'C'
    else:
        if last_my == 'D':
            if hostile or independent:
                return 'D'
            if exploitable:
                if my_d_streak >= 12:
                    return 'C'
                p = 0.85 if (rd_eff >= 3 and rdd_eff == 0) else 0.55
                return 'D' if rng.random() < p else 'C'
            if conditional:
                return 'C'
            if rd_eff >= 2 and p_punish < 0.60 and p_unprov < 0.35:
                return 'D' if rng.random() < 0.18 else 'C'
            return 'C'
        else:
            if hostile or independent:
                return 'D'
            if exploitable:
                if my_d_streak >= 12:
                    return 'C'
                p = 0.85 if (rd_eff >= 3 and rdd_eff == 0) else 0.55
                return 'D' if rng.random() < p else 'C'
            if conditional:
                return 'C'
            if opp_d == 0 and n >= 6 and n <= 85:
                if my_d == 0:
                    return 'D' if rng.random() < 0.04 else 'C'
                if rd_eff >= 1 and rdd_eff == 0:
                    return 'D' if rng.random() < 0.35 else 'C'
            if rd_eff >= 2 and p_punish < 0.60 and p_unprov < 0.35 and opp_d <= 2:
                return 'D' if rng.random() < 0.08 else 'C'
            return 'C'

    return 'C'
